// app/(auth)/login.tsx
import React, { useState } from 'react';
import { API_BASE_URL } from "../constants/config";
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  Dimensions,
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  Alert,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { BlurView } from 'expo-blur';
import { Ionicons } from '@expo/vector-icons';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import { useRouter } from 'expo-router';
import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';

const { width, height } = Dimensions.get('window');
const API_URL = `${API_BASE_URL}/login`;

interface LoginResponse {
  token: string;
  user: {
    id: number;
    name: string;
    email: string;
    role: 'driver' | 'passenger' | 'admin' | string;
  };
}

export default function LoginScreen() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [focusedField, setFocusedField] = useState<string | null>(null);

  // Animation values
  const emailScale = useSharedValue(1);
  const passwordScale = useSharedValue(1);
  const buttonScale = useSharedValue(1);

  const handleLogin = async () => {
    console.log('[Login] Starting login process...');
    
    if (!email || !password) {
      console.log('[Login] Validation failed: missing email or password');
      Alert.alert('Error', 'Please enter both email and password.');
      return;
    }

    setIsLoading(true);

    try {
      console.log('[Login] Sending request to API:', API_URL);
      const response = await axios.post<LoginResponse>(API_URL, { 
        email, 
        password 
      });
      console.log('[Login] API response received:', response.data);

      const { token, user } = response.data;

      // Save token
      await AsyncStorage.setItem('token', token);
      console.log('[Login] Token saved to AsyncStorage');

      // Save credentials if remember me is checked
      if (rememberMe) {
        await AsyncStorage.setItem('savedEmail', email);
        console.log('[Login] Email saved for Remember Me');
      }

      Alert.alert('Success', `Welcome back, ${user.name}! 🎉`);

      // Navigate based on role
      if (user.role === 'passenger') {
        router.replace('/(client)/home');
      } else if (user.role === 'driver') {
        router.replace('/(rider)/home');
      } else if (user.role === 'admin') {
        router.replace('/(admin)/home');
      } else {
        console.log('[Login] Unknown user role:', user.role);
        Alert.alert('Error', 'Unknown user role.');
      }
    } catch (error) {
      console.log('[Login] Login failed with error:', error);
      let errorMessage = 'Login failed. Please check your credentials.';
      
      if (axios.isAxiosError(error)) {
        if (error.response?.status === 401) {
          errorMessage = 'Invalid email or password.';
        } else if (error.response?.status === 500) {
          errorMessage = 'Server error. Please try again later.';
        } else {
          errorMessage = error.response?.data?.message || error.message;
        }
      }
      
      Alert.alert('Login Failed', errorMessage);
    } finally {
      console.log('[Login] Login process finished');
      setIsLoading(false);
    }
  };

  // Animated styles
  const emailAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: withSpring(emailScale.value) }],
  }));

  const passwordAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: withSpring(passwordScale.value) }],
  }));

  const buttonAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: withSpring(buttonScale.value) }],
  }));

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={styles.container}
    >
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* Animated Background Blobs */}
        <View style={styles.backgroundContainer}>
          <LinearGradient
            colors={['#a855f7', '#ec4899']}
            style={[styles.blob, styles.blob1]}
          />
          <LinearGradient
            colors={['#ec4899', '#3b82f6']}
            style={[styles.blob, styles.blob2]}
          />
          <LinearGradient
            colors={['#3b82f6', '#8b5cf6']}
            style={[styles.blob, styles.blob3]}
          />
        </View>

        {/* Floating Decorative Elements */}
        <View style={[styles.floatingElement, styles.floatingTop]}>
          <LinearGradient
            colors={['#ec4899', '#8b5cf6']}
            style={styles.floatingGradient}
          />
        </View>

        {/* Main Card with Glassmorphism */}
        <BlurView intensity={80} tint="light" style={styles.card}>
          {/* Decorative corner elements */}
          <View style={[styles.cornerDecor, styles.cornerTopRight]}>
            <LinearGradient
              colors={['#ec4899', '#8b5cf6']}
              style={styles.cornerGradient}
            />
          </View>
          <View style={[styles.cornerDecor, styles.cornerBottomLeft]}>
            <LinearGradient
              colors={['#3b82f6', '#8b5cf6']}
              style={styles.cornerGradient}
            />
          </View>

          {/* Logo Section */}
          <View style={styles.logoContainer}>
            <View style={styles.logoWrapper}>
              <LinearGradient
                colors={['#ec4899', '#8b5cf6', '#3b82f6']}
                style={styles.logoGradient}
              >
                <Ionicons name="car" size={48} color="#fff" />
              </LinearGradient>
              <View style={styles.logoShadow} />
            </View>
            <Text style={styles.title}>Bella Ride</Text>
            <Text style={styles.subtitle}>Your trusted women's taxi service</Text>
          </View>

          {/* Email Input */}
          <View style={styles.inputContainer}>
            <Text style={styles.label}>Email Address</Text>
            <Animated.View style={[emailAnimatedStyle]}>
              <View
                style={[
                  styles.inputWrapper,
                  focusedField === 'email' && styles.inputFocused,
                ]}
              >
                <View style={styles.inputContent}>
                  <Ionicons
                    name="mail"
                    size={20}
                    color="#9ca3af"
                    style={styles.inputIcon}
                  />
                  <TextInput
                    style={styles.input}
                    placeholder="your@email.com"
                    placeholderTextColor="#9ca3af"
                    value={email}
                    onChangeText={setEmail}
                    keyboardType="email-address"
                    autoCapitalize="none"
                    autoCorrect={false}
                    onFocus={() => {
                      setFocusedField('email');
                      emailScale.value = 1.02;
                    }}
                    onBlur={() => {
                      setFocusedField(null);
                      emailScale.value = 1;
                    }}
                  />
                </View>
              </View>
            </Animated.View>
          </View>

          {/* Password Input */}
          <View style={styles.inputContainer}>
            <Text style={styles.label}>Password</Text>
            <Animated.View style={[passwordAnimatedStyle]}>
              <View
                style={[
                  styles.inputWrapper,
                  focusedField === 'password' && styles.inputFocused,
                ]}
              >
                <View style={styles.inputContent}>
                  <Ionicons
                    name="lock-closed"
                    size={20}
                    color="#9ca3af"
                    style={styles.inputIcon}
                  />
                  <TextInput
                    style={[styles.input, styles.passwordInput]}
                    placeholder="Enter your password"
                    placeholderTextColor="#9ca3af"
                    value={password}
                    onChangeText={setPassword}
                    secureTextEntry={!showPassword}
                    onFocus={() => {
                      setFocusedField('password');
                      passwordScale.value = 1.02;
                    }}
                    onBlur={() => {
                      setFocusedField(null);
                      passwordScale.value = 1;
                    }}
                  />
                  <TouchableOpacity
                    onPress={() => setShowPassword(!showPassword)}
                    style={styles.eyeButton}
                  >
                    <Ionicons
                      name={showPassword ? 'eye-off' : 'eye'}
                      size={20}
                      color="#6b7280"
                    />
                  </TouchableOpacity>
                </View>
              </View>
            </Animated.View>
          </View>

          {/* Remember Me & Forgot Password */}
          <View style={styles.optionsRow}>
            <TouchableOpacity
              style={styles.rememberMe}
              onPress={() => setRememberMe(!rememberMe)}
            >
              <View
                style={[
                  styles.checkbox,
                  rememberMe && styles.checkboxChecked,
                ]}
              >
                {rememberMe && (
                  <Ionicons name="checkmark" size={16} color="#fff" />
                )}
              </View>
              <Text style={styles.rememberText}>Remember me</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={() => router.replace('/forgot-password')}>
              <Text style={styles.forgotText}>Forgot Password?</Text>
            </TouchableOpacity>
          </View>

          {/* Sign In Button */}
          <Animated.View style={buttonAnimatedStyle}>
            <TouchableOpacity
              activeOpacity={0.8}
              onPressIn={() => (buttonScale.value = 0.95)}
              onPressOut={() => (buttonScale.value = 1)}
              onPress={handleLogin}
              disabled={isLoading}
            >
              <LinearGradient
                colors={['#ec4899', '#8b5cf6', '#3b82f6']}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={styles.signInButton}
              >
                {isLoading ? (
                  <View style={styles.loadingContainer}>
                    <ActivityIndicator color="#fff" size="small" />
                    <Text style={styles.signInText}>Signing in...</Text>
                  </View>
                ) : (
                  <Text style={styles.signInText}>Sign In</Text>
                )}
              </LinearGradient>
            </TouchableOpacity>
          </Animated.View>

          {/* Divider */}
          <View style={styles.divider}>
            <View style={styles.dividerLine} />
            <Text style={styles.dividerText}>Or continue with</Text>
            <View style={styles.dividerLine} />
          </View>

          {/* Social Login Buttons */}
          <View style={styles.socialRow}>
            <TouchableOpacity 
              style={styles.socialButton}
              onPress={() => Alert.alert('Coming Soon', 'Google login will be available soon!')}
            >
              <View style={styles.socialContent}>
                <Text style={styles.googleText}>G</Text>
                <Text style={styles.socialLabel}>Google</Text>
              </View>
            </TouchableOpacity>
            <TouchableOpacity 
              style={[styles.socialButton, styles.appleButton]}
              onPress={() => Alert.alert('Coming Soon', 'Apple login will be available soon!')}
            >
              <View style={styles.socialContent}>
                <Ionicons name="logo-apple" size={20} color="#fff" />
                <Text style={[styles.socialLabel, styles.appleLabelText]}>
                  Apple
                </Text>
              </View>
            </TouchableOpacity>
          </View>

          {/* Sign Up Link */}
          <View style={styles.signUpContainer}>
            <Text style={styles.signUpText}>Don't have an account? </Text>
            <TouchableOpacity onPress={() => router.push('/register')}>
              <Text style={styles.signUpLink}>Sign Up</Text>
            </TouchableOpacity>
          </View>
        </BlurView>

        {/* Floating Badges */}
        <View style={[styles.badge, styles.verifiedBadge]}>
          <LinearGradient
            colors={['#10b981', '#059669']}
            style={styles.badgeGradient}
          >
            <Text style={styles.badgeText}>✓ Verified</Text>
          </LinearGradient>
        </View>
        <View style={[styles.badge, styles.secureBadge]}>
          <LinearGradient
            colors={['#3b82f6', '#6366f1']}
            style={styles.badgeGradient}
          >
            <Text style={styles.badgeText}>🔒 Secure</Text>
          </LinearGradient>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

